```js
// src/server.js (or wherever you start the app)
require('express-async-errors');          // helpful for async route errors
const express = require('express');
const app = express();

// ---------- Secrets retrieval ----------
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function loadSecrets() {
  const client = new SecretsManagerClient({ region: 'us-east-1' });
  const command = new GetSecretValueCommand({ SecretId: 'myAppSecret' });
  const response = await client.send(command);
  // Assume secret is stored as JSON: {"DB_PASSWORD":"s3cr3t","API_KEY":"abcd…"}
  return JSON.parse(response.SecretString);
}

// ---------- Application start ----------
(async () => {
  const secrets = await loadSecrets();          // <-- secrets now in memory only
  const db = require('./db')(secrets.DB_PASSWORD); // pass password securely

  // Simple health endpoint (unchanged)
  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  // Example protected endpoint that uses a secret
  app.get('/protected-data', async (req, res) => {
    const data = await db.fetchSensitive();  // uses the password stored only in memory
    res.json(data);
  });

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
})();
```

**Key points in the refactor**

| ✅ | What it achieves |
|---|-------------------|
| **No `.env` for secrets** | Secrets are never written to disk. |
| **Least‑privilege IAM** | The container’s role only needs `secretsmanager:GetSecretValue` on the specific secret. |
| **In‑memory only** | Once the secret is fetched it lives only in the process memory; it’s never persisted. |
| **Centralised rotation** | Changing the secret in the vault instantly propagates to all instances after they restart (or even on‑the‑fly with caching logic). |

