/* -------------------------------------------------------------------------
 * app.js – Hardened Express API
 * -------------------------------------------------------------------------
 * Security hardening includes:
 *   • Helmet for secure HTTP headers
 *   • CORS policy (tight default, change as needed)
 *   • Rate limiting (basic DoS protection)
