  // You could also filter the list based on req.user.role, etc.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

// ---------------------------------------------------
// 7️⃣ Central error handler (must be after all routes)
// ---------------------------------------------------
app.use((err, req, res, next) => {
  // Log the full error stack for dev/ops
  logger.error('Unhandled error', { message: err.message, stack: err.stack });

  // Do **not** leak internal details to the client
  const status = err.status || 500;
  const safeMessage = status === 500 ? 'Internal server error' : err.message;
  res.status(status).json({ error: safeMessage });
});

// ---------------------------------------------------
// 8️⃣ Server start – use env var, default to 3000
// ---------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;
