## 4. Validation Example (Future POST /users)

If you later add routes that accept user input (e.g., `POST /users`), **always** validate/coerce data before using it.

```javascript
const { body, validationResult } = require('express-validator');

app.post(
  '/users',
  authenticate,
  [
    body('name')
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2‑50 characters'),
    body('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email required')
  ],
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(422).json({ errors: errors.array() });
    }

    // At this point `req.body` is safe to pass to a DB driver that uses
    // parameterised statements (e.g., knex, Sequelize, Mongoose, etc.)
    // Example: await db.users.insert(req.body);
    res.status(201).json({ message: 'User created' });
  }
);
```

