```js
// app.js – after creating the `app` instance
const helmet = require('helmet');
const cors = require('cors');

// Security headers
app.use(helmet());

// Remove Express default X-Powered-By header
app.disable('x-powered-by');

// CORS – restrict to trusted origins (adjust as needed)
app.use(
  cors({
    origin: process.env.CORS_ORIGIN || 'https://my‑frontend.example.com',
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);
```

### 2. Enforce HTTPS (in production)

If you run behind a reverse proxy (NGINX, Cloud‑load‑balancer, etc.) set `trust proxy` and redirect HTTP → HTTPS:

```js
if (process.env.NODE_ENV === 'production') {
  app.enable('trust proxy'); // needed for correct req.protocol detection
  app.use((req, res, next) => {
    if (req.secure) {
      return next();
    }
    // redirect to HTTPS
    res.redirect(`https://${req.headers.host}${req.originalUrl}`);
  });
}
```

> **Note:** In a container environment the TLS termination usually happens at the load balancer, so `trust proxy` is essential for the redirect to work correctly.

### 3. Add Rate Limiting (protect against DoS / credential‑stuffing)

```bash
npm install express-rate-limit
```

```js
const rateLimit = require('express-rate-limit');

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/users', apiLimiter); // apply only to sensitive routes
// or app.use(apiLimiter) for global protection
```

### 4. Implement Proper Authentication & Authorization

For demonstration, use **JWT** (you can swap for OAuth2, sessions, etc.):

```bash
npm install jsonwebtoken bcryptjs
```

Create a small auth module:

```js
// auth.js
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

const SECRET = process.env.JWT_SECRET || 'change‑me‑in‑prod';

// simple mock user store (replace with DB)
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com', passwordHash: bcrypt.hashSync('alicePwd', 10) },
  { id: 2, name: 'Bob',   email: 'bob@example.com',   passwordHash: bcrypt.hashSync('bobPwd', 10) },
];

function generateToken(user) {
  return jwt.sign({ sub: user.id, name: user.name }, SECRET, { expiresIn: '1h' });
}

function verifyToken(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }
  const token = auth.split(' ')[1];
  try {
    req.user = jwt.verify(token, SECRET);
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

module.exports = { generateToken, verifyToken, users };
```

Protect the `/users` endpoint:

```js
const { verifyToken } = require('./auth');

app.get('/users', verifyToken, (req, res) => {
  // Return only non‑sensitive fields, e.g. omit email if not needed
  const safeUsers = users.map(u => ({ id: u.id, name: u.name }));
  res.json(safeUsers);
});
```

Add a **login** route:

```js
app.post('/login', express.json(), (req, res) => {
  const { email, password } = req.body;
  const user = users.find(u => u.email === email);
  if (!user || !bcrypt.compareSync(password, user.passwordHash)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const token = generateToken(user);
  res.json({ token });
});
```

> **Why?**  
> * Authentication prevents unauthenticated enumeration of users.  
> * Authorization (the `verifyToken` middleware) is a single point you can extend with role‑checks.

