## 4. Sample implementation – **AWS Secrets Manager**

Below is a minimal wrapper you can drop into the project (`secrets.js`). It loads **JWT secret** and **DB credentials** from AWS Secrets Manager and makes them available through a simple `await getSecret(name)` call.

```js
// secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// The region can be set via AWS_REGION env var (no hard‑coding)
const client = new SecretsManagerClient({});

/**
 * Fetch a secret (JSON‑encoded) from AWS Secrets Manager.
 * @param {string} secretName - The full ARN or friendly name of the secret.
 * @returns {Promise<Object>} Parsed JSON secret.
 */
async function getSecret(secretName) {
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(command);

  // Secrets Manager can return either SecretString or SecretBinary.
  const secretString = response.SecretString
    ? response.SecretString
    : Buffer.from(response.SecretBinary, 'base64').toString('utf-8');

  try {
    return JSON.parse(secretString);
  } catch (_) {
    // If the secret isn’t JSON, just return the raw string.
    return secretString;
  }
}

// Convenience for the specific secrets our app needs
async function loadAppSecrets() {
  const jwt = await getSecret(process.env.JWT_SECRET_ARN);
  const db = await getSecret(process.env.DB_CREDENTIALS_ARN);
  return { jwt, db };
}

module.exports = { loadAppSecrets, getSecret };
```

**How to use it in `app.js`**

```js
require('dotenv').config();                     // Only for non‑secret config (e.g., ARNs)
const { loadAppSecrets } = require('./secrets');

(async () => {
  const { jwt, db } = await loadAppSecrets();

  // Store into process.env (or a dedicated config object)
  process.env.JWT_SECRET = jwt.key;            // Example secret shape: { "key": "super‑random‑value" }
  process.env.DB_USER = db.username;
  process.env.DB_PASS = db.password;
  process.env.DB_HOST = db.host;
  process.env.DB_NAME = db.database;

  // Now start the server – everything else can read from process.env as before
  require('./server');                         // <-- your existing server init code
})();
```

**Deploy‑time notes**

| Step | What to do |
|------|------------|
| **Create secrets** | In the AWS console or CLI: `aws secretsmanager create-secret --name jwt-secret --secret-string '{"key":"<random‑256‑bit>"}'` |
| **Grant IAM permission** | Attach a policy like `{ "Effect":"Allow", "Action":["secretsmanager:GetSecretValue"], "Resource":["arn:aws:secretsmanager:region:account-id:secret:jwt-secret*"] }` to the EC2/ECS task role. |
| **Set ARNs as env vars** | `JWT_SECRET_ARN=arn:aws:secretsmanager:…:secret:jwt-secret‑abcd` and `DB_CREDENTIALS_ARN=…` in the task definition or container spec (these are the only *plain* environment variables you keep). |

