## 5. Sample implementation – **Azure Key Vault**

```js
// azureSecrets.js
const { DefaultAzureCredential } = require('@azure/identity');
const { SecretClient } = require('@azure/keyvault-secrets');

const credential = new DefaultAzureCredential();   // Works with Managed Identity, VS Code, CLI, etc.
const vaultUrl = process.env.KEY_VAULT_URL;        // e.g. https://my‑vault.vault.azure.net
const client = new SecretClient(vaultUrl, credential);

async function getSecret(name) {
  const secret = await client.getSecret(name);
  try {
    return JSON.parse(secret.value);
  } catch (_) {
    return secret.value;
  }
}

// Example usage
(async () => {
  const jwt = await getSecret('jwt-secret');           // stored as plain string or JSON
  const db = await getSecret('db-credentials');        // {"username":"…","password":"…"}
  process.env.JWT_SECRET = jwt.key ?? jwt;
  Object.assign(process.env, {
    DB_USER: db.username,
    DB_PASS: db.password,
    DB_HOST: db.host,
    DB_NAME: db.database,
  });
  require('./server');
})();
```

*Deploy*: give the Azure App Service / VM a **Managed Identity** and assign it the **Key Vault Secrets User** role for the specific secrets.

