);

// Body parsing (useful when you later add POST/PUT endpoints)
app.use(express.json());

// Request logging – helps with A09 (Logging & Monitoring)
app.use(
  morgan('combined', {
    skip: (req, res) => res.statusCode < 400, // only log warnings/errors by default
    stream: process.stdout,
  })
);

// --------------------------------------------------------------
// 3️⃣  Routes (with basic auth for sensitive data)
// --------------------------------------------------------------
