});

// Protect the user list – demonstration of A01 (Broken Access Control)
app.get(
  '/users',
  basicAuth({
    users: USERS,
    challenge: true, // sends WWW‑Authenticate header
    unauthorizedResponse: () => ({ error: 'Unauthorized' }),
  }),
  (req, res) => {
    // In a real app, fetch from DB with parameterised queries.
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// --------------------------------------------------------------
// 4️⃣  Global error handler (prevents stack traces leaking)
// --------------------------------------------------------------
app.use((err, req, res, next) => {
  console.error(err); // still log to console / file for ops
  res.status(500).json({ error: 'Internal Server Error' });
});

// --------------------------------------------------------------
// 5️⃣  Server bootstrap (HTTPS enforcement)
// --------------------------------------------------------------
const http = require('http');
const https = require('https');
const fs = require('fs');

// Prefer HTTPS; fall back to HTTP only in dev (controlled by NODE_ENV)
if (process.env.NODE_ENV === 'production') {
  const httpsOptions = {
    key: fs.readFileSync(process.env.TLS_KEY_PATH),
    cert: fs.readFileSync(process.env.TLS_CERT_PATH),
  };
  https.createServer(httpsOptions, app).listen(443, () => {
    console.log('HTTPS server running on port 443');
  });
} else {
  const port = process.env.PORT || 3000;
  http.createServer(app).listen(port, () => {
    console.log(`HTTP server running on port ${port} (development)`);
