// CORS – adjust origin list for your front‑ends
app.use(cors({
  origin: process.env.CORS_ORIGIN?.split(',') || ['https://example.com'],
  methods: ['GET','POST','PUT','DELETE','OPTIONS'],
  credentials: true,
}));

