## 2️⃣ Add Authentication & Authorization (A01 / A07)

A production API should never expose user data without proper auth. Below is a simple **JWT‑based** example using `express-jwt` and `jsonwebtoken`. Feel free to replace with OAuth2, session‑based auth, etc.

```bash
npm install jsonwebtoken express-jwt
```

```js
// After the security middleware section, before routes:

const jwt = require('jsonwebtoken');
const { expressjwt: jwtMiddleware } = require('express-jwt');

// Secret should be stored securely (env‑var, vault, etc.)
const JWT_SECRET = process.env.JWT_SECRET || 'changeMeImmediately!';

// Helper to issue tokens (e.g., in a real /login route)
function issueToken(payload) {
  return jwt.sign(payload, JWT_SECRET, { expiresIn: '1h' });
}

// Protect all routes *except* health & login
app.use(
  jwtMiddleware({
    secret: JWT_SECRET,
    algorithms: ['HS256'],
  }).unless({ path: ['/health', '/login'] })
);

// Example login endpoint (replace with real credential check)
app.post('/login', (req, res) => {
  const { username, password } = req.body;
  // TODO: Validate credentials against DB / LDAP
  if (username === 'admin' && password === 's3cr3t') {
    const token = issueToken({ sub: username, role: 'admin' });
    return res.json({ token });
  }
  return res.status(401).json({ error: 'Invalid credentials' });
});
```

### Protect `/users` with a role check

```js
function requireRole(role) {
  return (req, res, next) => {
    if (req.auth && req.auth.role === role) return next();
    return res.status(403).json({ error: 'Forbidden' });
  };
}

// Only admins can list users
app.get('/users', requireRole('admin'), (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Why?**  
- **Authentication** ensures only legitimate principals can call the API.  
- **Authorization** (role‑based) enforces the principle of least privilege (A01, A07).  

---

## 3️⃣ Input Validation & Sanitisation (A03 – Injection, A10 – SSRF)

Even though the current app has no request bodies, you will inevitably add them. Use **express‑validator** (or Joi/Zod) for systematic validation.

```bash
npm install express-validator
```

```js
const { body, param, query, validationResult } = require('express-validator');

// Example: safe user‑creation endpoint
app.post(
  '/users',
  requireRole('admin'), // protected
  [
    body('name').isString().isLength({ min: 1, max: 100 }).trim(),
    body('email').isEmail().normalizeEmail(),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // At this point `req.body` is guaranteed to be the type we expect.
    // Insert into DB using parameterised queries / ORM to avoid SQLi.
    // ...
    res.status(201).json({ message: 'User created' });
  }
);
```

If you ever need to fetch remote resources (potential SSRF), **whitelist** allowed hosts and use the `url` module for parsing.

```js
const { URL } = require('url');
const allowedHosts = new Set(['api.trusted.com', 'static.example.org']);

app.get('/proxy', (req, res) => {
  try {
    const target = new URL(req.query.url);
    if (!allowedHosts.has(target.hostname)) {
      return res.status(400).json({ error: 'Host not allowed' });
    }
    // safe fetch logic …
  } catch (_) {
    return res.status(400).json({ error: 'Invalid URL' });
  }
});
```

**Why?**  
- Guarantees that user‑supplied data cannot break query syntax, escape contexts, or direct server‑side network calls (A03, A10).  

