Below is a **minimal, production‑ready pattern** that works with any of the three approaches (environment variables, AWS Secrets Manager, or Vault). It centralises configuration, validates required secrets, and avoids loading them more than once.

```js
// config.js – central place for all configuration & secret loading
const fs   = require('fs');
const path = require('path');

if (process.env.NODE_ENV !== 'production') {
  // Load .env only for local development; in prod the vars must already exist
  require('dotenv').config();
}

/**
 * Helper that throws if a required variable is missing.
 */
function required(name) {
  const val = process.env[name];
  if (!val) {
    throw new Error(`❗️ Missing required environment variable: ${name}`);
  }
  return val;
}

/* -----------------------------------------------------------------
 * Secrets that are *always* supplied via the environment (e.g. from
 * a container orchestrator). This is the simplest and most portable
 * approach for many CI/CD pipelines.
 * ----------------------------------------------------------------- */
const JWT_SECRET   = required('JWT_SECRET');
const DB_URL       = required('DATABASE_URL');

/* -----------------------------------------------------------------
 * OPTIONAL – Pull additional secrets from a cloud manager IF you
 * enable the feature via an env flag.
 * ----------------------------------------------------------------- */
let extraSecrets = {};

if (process.env.USE_AWS_SECRETS === 'true') {
  const { getSecret } = require('./awsSecrets');   // see example 2 above
  (async () => {
    extraSecrets = await getSecret('my-app/prod/extra');
    // e.g., extraSecrets = { thirdPartyApiKey: 'abc123' }
  })().catch(err => {
    console.error('Failed to load AWS Secrets Manager secrets', err);
    process.exit(1);
  });
}

/* -----------------------------------------------------------------
 * Export a frozen config object – any module can `require('./config')`
 * ----------------------------------------------------------------- */
module.exports = Object.freeze({
  jwtSecret: JWT_SECRET,
  dbUrl: DB_URL,
  ...extraSecrets,
});
```

**Usage inside `app.js`**

```js
const config = require('./config');
// Now you can safely use config.jwtSecret, config.dbUrl, etc.
// Example: JWT middleware
const jwt = require('express-jwt');
app.use(jwt({ secret: config.jwtSecret, algorithms: ['HS256'] }).unless({ path: ['/health'] }));
```

*Benefits of this pattern*

| Benefit | Why it matters |
|---------|----------------|
| **Single source of truth** | All parts of the app read from `config.js` → no duplicated `process.env` look‑ups. |
| **Fail‑fast on missing secrets** | The `required()` helper throws at start‑up, preventing the server from running in a mis‑configured state. |
| **Pluggable secret back‑ends** | By toggling `USE_AWS_SECRETS` (or a similar flag) you can switch between plain env vars and a secrets manager without code changes. |
| **Immutable config** | `Object.freeze` prevents accidental mutation at runtime. |

