### 2.1. Add Security‑Focused Middleware

```js
// app.js
require('dotenv').config();               // Load environment variables from .env
const express = require('express');
const helmet = require('helmet');         // Secure HTTP headers
const cors = require('cors');             // Control cross‑origin requests
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');         // Request logging
const { body, query, validationResult } = require('express-validator'); // Input validation

const app = express();

// ---------- Security Middleware ----------
app.use(helmet());                         // Sets CSP, HSTS, X‑Content‑Type‑Options, etc.
app.use(cors({                               // Adjust origin list to your client domains
  origin: process.env.CORS_ORIGIN || '*', // In production replace '*' with explicit whitelist
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));
app.use(express.json());                  // Parse JSON bodies safely
app.use(express.urlencoded({ extended: true }));

// Rate limiting – mitigates brute‑force & DoS
