const rateLimit = require('express-rate-limit'); // DDOS protection
const morgan = require('morgan');           // Request logging
const app = express();

// ---------- Middleware ----------
app.use(helmet());                          // Sets CSP, HSTS, X‑XSS‑Protection, etc.
app.use(cors({                              // Restrict origins in production
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
app.use(express.json());                    // Body parser for future POST/PUT
app.use(morgan('combined'));                // Logs to stdout (or file in prod)

// Rate limiter – adjust limits for your traffic profile
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---------- Health endpoint ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------- Secure Users endpoint ----------
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com' },
];

// Simple token‑based auth (replace with JWT / OAuth2 in real apps)
function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed token' });
  }
  const token = authHeader.split(' ')[1];
  // 👉 In production verify the token signature, expiration, scopes, etc.
  if (token !== process.env.API_TOKEN) {
    return res.status(403).json({ error: 'Invalid token' });
  }
  next();
}

app.get('/users', requireAuth, (req, res) => {
  // Defensive copy – never expose internal mutable structures
  res.json(JSON.parse(JSON.stringify(USERS)));
});

// ---------- Global error handler ----------
app.use((err, req, res, next) => {
  console.error(err); // In prod replace with a structured logger (winston, pino)
  res.status(500).json({ error: 'Internal Server Error' });
});

// ---------- Server bootstrap ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

#### What this adds

| Feature | Why it matters |
|---------|----------------|
| **dotenv** | Keeps secrets (tokens, ports) out of source control. |
| **helmet** | Adds 15+ security headers (`Content‑Security‑Policy`, `Strict‑Transport‑Security`, `X‑Content‑Type‑Options`, etc.). |
| **cors** | Controls which origins can call your API; avoid `*` in production. |
| **express‑rate‑limit** | Mitigates brute‑force and DoS attacks. |
| **morgan** | Provides access logs, essential for forensic investigations and compliance. |
| **requireAuth middleware** | Implements a very simple token check—illustrates where you’d plug in JWT/OAuth2. |
| **global error handler** | Prevents stack traces from leaking to clients and guarantees a consistent JSON error shape. |
| **environment‑driven port** | Makes the app container‑friendly and easier to configure per environment. |

### 3.2 Harden Input Validation (Future‑Proof)

When you start accepting request bodies or URL parameters, add a validation layer such as **Joi**, **express‑validator**, or **Zod**.

Example using `express-validator`:

```bash
npm install express-validator
```

```js
const { body, param, validationResult } = require('express-validator');

// Example POST /users (create user)
app.post(
  '/users',
  requireAuth,
  [
    body('name')
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be 2‑50 characters long'),
    body('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email required')
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // 400 Bad Request with detailed validation errors
      return res.status(400).json({ errors: errors.array() });
    }
    // safe data: req.body.name, req.body.email
    // …insert into DB with parameterised queries / ORM
    res.status(201).json({ message: 'User created' });
  }
);
```

*All user‑supplied data is now validated, sanitized, and never concatenated into raw SQL or command strings – which eliminates injection risks.*

### 3.3 Enforce HTTPS & HSTS

If you terminate TLS in a reverse proxy (NGINX, ELB, Cloudflare, etc.) you should still send the `Strict-Transport-Security` header:

```js
app.use(
  helmet({
    hsts: {
      maxAge: 31536000, // 1 year in seconds
      includeSubDomains: true,
      preload: true,
    },
  })
);
```

If you serve TLS directly from Node, you can start with:

```js
const https = require('https');
const fs = require('fs');

const server = https.createServer(
  {
    key: fs.readFileSync('path/to/private.key'),
    cert: fs.readFileSync('path/to/certificate.crt')
  },
  app
);
server.listen(PORT, () => console.log(`HTTPS server listening on ${PORT}`));
```

### 3.4 Secure Logging & Monitoring

* Replace `console.log`/`console.error` with a structured logger (e.g., **pino** or **winston**) that can forward logs to a log aggregation service (ELK, Splunk, Datadog).
* Log authentication failures, rate‑limit events, and any unexpected errors.
* Set up health‑check alerts on `/health` endpoint (status not `ok` → pager/Slack).

### 3.5 Dependency Hygiene

Run the following and fix any reported high‑severity issues:

```bash
npm audit
npm audit fix --force   # after confirming no breaking changes
```

Lock versions in `package-lock.json` and consider using **npm shrinkwrap** or **yarn.lock** in production pipelines.

### 3.6 Deploy‑time Security Checklist

| Checklist Item | Action |
|----------------|--------|
| **Environment secrets** | Store `API_TOKEN`, DB credentials, etc., in a secret manager (AWS Secrets Manager, HashiCorp Vault, .env files not committed). |
| **Run as non‑root** | In Dockerfile, use a non‑root user (`USER node`). |
| **Expose only needed ports** | `EXPOSE 3000` (or 443 if you serve HTTPS). |
| **Container scanning** | Use tools like **Trivy**, **Snyk**, or **Clair** to scan images for CVEs. |
| **Runtime security** | Enable `NODE_ENV=production` to disable stack traces and debugging middleware. |
| **CSP** | Adjust `helmet.contentSecurityPolicy` if you ever serve HTML/JS. |

